/**
 * Volunteerhub database schema (Drizzle ORM, SQLite / Cloudflare D1).
 *
 * Money is stored as whole hryvnias (integer UAH). Timestamps are unix
 * milliseconds. IDs are random strings generated by the application.
 */
import { sql } from "drizzle-orm";
import { index, integer, primaryKey, sqliteTable, text, uniqueIndex, blob } from "drizzle-orm/sqlite-core";

const now = sql`(unixepoch() * 1000)`;

export const users = sqliteTable(
  "users",
  {
    id: text("id").primaryKey(),
    email: text("email").notNull(),
    /** null for demo organizers: such accounts cannot sign in. */
    passwordHash: text("password_hash"),
    name: text("name").notNull(),
    bio: text("bio").notNull().default(""),
    city: text("city").notNull().default(""),
    avatarFileId: text("avatar_file_id"),
    /** user | admin. Everyone can be both donor and organizer. */
    role: text("role").notNull().default("user"),
    /** Subscription plan structure (billing is not implemented yet). */
    plan: text("plan").notNull().default("free"),
    /** Set only when an admin approved an identity verification request. */
    identityVerifiedAt: integer("identity_verified_at"),
    /** JSON array of category slugs the user is interested in. */
    interests: text("interests").notNull().default("[]"),
    referralCode: text("referral_code").notNull(),
    referredBy: text("referred_by"),
    xp: integer("xp").notNull().default(0),
    isDemo: integer("is_demo", { mode: "boolean" }).notNull().default(false),
    isBlocked: integer("is_blocked", { mode: "boolean" }).notNull().default(false),
    createdAt: integer("created_at").notNull().default(now),
  },
  (t) => [uniqueIndex("users_email_uq").on(t.email), uniqueIndex("users_ref_uq").on(t.referralCode)],
);

export const sessions = sqliteTable(
  "sessions",
  {
    /** SHA-256 of the session token; the raw token only lives in the cookie. */
    id: text("id").primaryKey(),
    userId: text("user_id").notNull(),
    expiresAt: integer("expires_at").notNull(),
    createdAt: integer("created_at").notNull().default(now),
  },
  (t) => [index("sessions_user_idx").on(t.userId)],
);

export const loginAttempts = sqliteTable(
  "login_attempts",
  {
    key: text("key").notNull(),
    windowStart: integer("window_start").notNull(),
    count: integer("count").notNull().default(0),
  },
  (t) => [primaryKey({ columns: [t.key, t.windowStart] })],
);

export const files = sqliteTable(
  "files",
  {
    id: text("id").primaryKey(),
    ownerId: text("owner_id").notNull(),
    name: text("name").notNull(),
    mime: text("mime").notNull(),
    size: integer("size").notNull(),
    /** public: campaign media & attachments. private: verification documents. */
    visibility: text("visibility").notNull().default("public"),
    /** Inline storage (MVP). When an R2 bucket is bound, `storageKey` is used instead. */
    data: blob("data", { mode: "buffer" }),
    storageKey: text("storage_key"),
    createdAt: integer("created_at").notNull().default(now),
  },
  (t) => [index("files_owner_idx").on(t.ownerId)],
);

export const campaigns = sqliteTable(
  "campaigns",
  {
    id: text("id").primaryKey(),
    slug: text("slug").notNull(),
    organizerId: text("organizer_id").notNull(),
    title: text("title").notNull(),
    summary: text("summary").notNull().default(""),
    description: text("description").notNull().default(""),
    category: text("category").notNull(),
    city: text("city").notNull().default(""),
    coverFileId: text("cover_file_id"),
    goalAmount: integer("goal_amount").notNull().default(0),
    /** Amount reported by the organizer. Never synced automatically (no official API). */
    raisedAmount: integer("raised_amount").notNull().default(0),
    raisedUpdatedAt: integer("raised_updated_at"),
    deadline: integer("deadline"),
    urgent: integer("urgent", { mode: "boolean" }).notNull().default(false),
    jarUrl: text("jar_url"),
    jarId: text("jar_id"),
    /** draft | pending | active | goal_reached | completed | rejected */
    status: text("status").notNull().default("draft"),
    rejectionReason: text("rejection_reason"),
    /** Set by a moderator when approving: the description & purpose were reviewed. */
    purposeReviewedAt: integer("purpose_reviewed_at"),
    /** Set by a moderator who opened the jar and matched it to the organizer. */
    destinationVerifiedAt: integer("destination_verified_at"),
    viewCount: integer("view_count").notNull().default(0),
    donateClicks: integer("donate_clicks").notNull().default(0),
    isDemo: integer("is_demo", { mode: "boolean" }).notNull().default(false),
    submittedAt: integer("submitted_at"),
    publishedAt: integer("published_at"),
    goalReachedAt: integer("goal_reached_at"),
    completedAt: integer("completed_at"),
    createdAt: integer("created_at").notNull().default(now),
    updatedAt: integer("updated_at").notNull().default(now),
  },
  (t) => [
    uniqueIndex("campaigns_slug_uq").on(t.slug),
    index("campaigns_status_idx").on(t.status),
    index("campaigns_org_idx").on(t.organizerId),
  ],
);

export const budgetItems = sqliteTable(
  "budget_items",
  {
    id: text("id").primaryKey(),
    campaignId: text("campaign_id").notNull(),
    label: text("label").notNull(),
    amount: integer("amount").notNull(),
    position: integer("position").notNull().default(0),
  },
  (t) => [index("budget_campaign_idx").on(t.campaignId)],
);

/** Public campaign attachments (documents, images). Private docs live in verification_requests. */
export const campaignAttachments = sqliteTable(
  "campaign_attachments",
  {
    id: text("id").primaryKey(),
    campaignId: text("campaign_id").notNull(),
    fileId: text("file_id").notNull(),
    title: text("title").notNull(),
    createdAt: integer("created_at").notNull().default(now),
  },
  (t) => [index("attach_campaign_idx").on(t.campaignId)],
);

export const campaignUpdates = sqliteTable(
  "campaign_updates",
  {
    id: text("id").primaryKey(),
    campaignId: text("campaign_id").notNull(),
    authorId: text("author_id").notNull(),
    /** update | purchase | final_report */
    kind: text("kind").notNull().default("update"),
    title: text("title").notNull(),
    body: text("body").notNull(),
    spentAmount: integer("spent_amount"),
    /** JSON array of public file ids (receipts, photos). */
    fileIds: text("file_ids").notNull().default("[]"),
    createdAt: integer("created_at").notNull().default(now),
  },
  (t) => [index("updates_campaign_idx").on(t.campaignId)],
);

export const follows = sqliteTable(
  "follows",
  {
    userId: text("user_id").notNull(),
    campaignId: text("campaign_id").notNull(),
    createdAt: integer("created_at").notNull().default(now),
  },
  (t) => [primaryKey({ columns: [t.userId, t.campaignId] }), index("follows_campaign_idx").on(t.campaignId)],
);

export const saves = sqliteTable(
  "saves",
  {
    userId: text("user_id").notNull(),
    campaignId: text("campaign_id").notNull(),
    createdAt: integer("created_at").notNull().default(now),
  },
  (t) => [primaryKey({ columns: [t.userId, t.campaignId] })],
);

export const shares = sqliteTable(
  "shares",
  {
    id: text("id").primaryKey(),
    userId: text("user_id").notNull(),
    campaignId: text("campaign_id").notNull(),
    channel: text("channel").notNull(),
    createdAt: integer("created_at").notNull().default(now),
  },
  (t) => [index("shares_user_idx").on(t.userId), index("shares_campaign_idx").on(t.campaignId)],
);

/** One row per unique visitor per campaign per day — used for fair-discovery exposure. */
export const campaignViews = sqliteTable(
  "campaign_views",
  {
    campaignId: text("campaign_id").notNull(),
    visitorHash: text("visitor_hash").notNull(),
    day: text("day").notNull(),
    referrerId: text("referrer_id"),
  },
  (t) => [primaryKey({ columns: [t.campaignId, t.visitorHash, t.day] })],
);

/** Unique visitors brought by a user's referral link. */
export const referralVisits = sqliteTable(
  "referral_visits",
  {
    referrerId: text("referrer_id").notNull(),
    campaignId: text("campaign_id").notNull(),
    visitorHash: text("visitor_hash").notNull(),
    createdAt: integer("created_at").notNull().default(now),
  },
  (t) => [primaryKey({ columns: [t.referrerId, t.campaignId, t.visitorHash] })],
);

/**
 * Ledger of awarded XP. The unique (user, action, refKey) index guarantees that
 * repeating the same action never awards XP twice.
 */
export const xpEvents = sqliteTable(
  "xp_events",
  {
    id: text("id").primaryKey(),
    userId: text("user_id").notNull(),
    action: text("action").notNull(),
    refKey: text("ref_key").notNull(),
    xp: integer("xp").notNull(),
    createdAt: integer("created_at").notNull().default(now),
  },
  (t) => [uniqueIndex("xp_unique").on(t.userId, t.action, t.refKey), index("xp_user_idx").on(t.userId)],
);

export const userAchievements = sqliteTable(
  "user_achievements",
  {
    userId: text("user_id").notNull(),
    code: text("code").notNull(),
    earnedAt: integer("earned_at").notNull().default(now),
  },
  (t) => [primaryKey({ columns: [t.userId, t.code] })],
);

/** Communities: universities, student orgs, companies, volunteer teams. Ready for corporate workspaces. */
export const communities = sqliteTable(
  "communities",
  {
    id: text("id").primaryKey(),
    slug: text("slug").notNull(),
    name: text("name").notNull(),
    /** university | student_org | company | volunteer_team */
    kind: text("kind").notNull(),
    description: text("description").notNull().default(""),
    createdBy: text("created_by").notNull(),
    isDemo: integer("is_demo", { mode: "boolean" }).notNull().default(false),
    createdAt: integer("created_at").notNull().default(now),
  },
  (t) => [uniqueIndex("communities_slug_uq").on(t.slug)],
);

export const communityMembers = sqliteTable(
  "community_members",
  {
    communityId: text("community_id").notNull(),
    userId: text("user_id").notNull(),
    role: text("role").notNull().default("member"),
    joinedAt: integer("joined_at").notNull().default(now),
  },
  (t) => [primaryKey({ columns: [t.communityId, t.userId] }), index("members_user_idx").on(t.userId)],
);

export const challenges = sqliteTable("challenges", {
  id: text("id").primaryKey(),
  /** null = platform-wide challenge */
  communityId: text("community_id"),
  title: text("title").notNull(),
  description: text("description").notNull(),
  /** shares_verified | follows_new | referrals | updates_read */
  metric: text("metric").notNull(),
  target: integer("target").notNull(),
  startsAt: integer("starts_at").notNull(),
  endsAt: integer("ends_at").notNull(),
  createdAt: integer("created_at").notNull().default(now),
});

export const challengeParticipants = sqliteTable(
  "challenge_participants",
  {
    challengeId: text("challenge_id").notNull(),
    userId: text("user_id").notNull(),
    joinedAt: integer("joined_at").notNull().default(now),
  },
  (t) => [primaryKey({ columns: [t.challengeId, t.userId] })],
);

export const verificationRequests = sqliteTable(
  "verification_requests",
  {
    id: text("id").primaryKey(),
    userId: text("user_id").notNull(),
    note: text("note").notNull().default(""),
    /** Private file — only the owner and admins can download it. */
    fileId: text("file_id"),
    /** pending | approved | rejected */
    status: text("status").notNull().default("pending"),
    reviewerId: text("reviewer_id"),
    reviewNote: text("review_note"),
    reviewedAt: integer("reviewed_at"),
    createdAt: integer("created_at").notNull().default(now),
  },
  (t) => [index("verif_user_idx").on(t.userId)],
);

export const contentReports = sqliteTable("content_reports", {
  id: text("id").primaryKey(),
  campaignId: text("campaign_id").notNull(),
  reporterId: text("reporter_id"),
  reason: text("reason").notNull(),
  details: text("details").notNull().default(""),
  /** open | resolved | dismissed */
  status: text("status").notNull().default("open"),
  resolvedBy: text("resolved_by"),
  createdAt: integer("created_at").notNull().default(now),
});

export type User = typeof users.$inferSelect;
export type Campaign = typeof campaigns.$inferSelect;
